# CODIGO CORRETO
# ALGORITMO: ENTRADA (Usuário) + PROCESSAMENTO (ULA) + SAÍDA (Objetivo)

try:
    # ENTRADA
    d1 = int(input('Digite o primeiro valor: '))
    d2 = int(input('Digite o segundo valor: '))
    d3 = int(input('Digite o terceiro valor: '))
    d4 = int(input('Digite o quarto valor: '))

    # PROCESSAMENTO
    senha = d1 * 1000 + d2 * 100 + d3 * 10 + d4

    if (d1 != d2 and d1 != d3 and d1 != d4
        and d2 != d3 and d2 != d4 and d3 != d4
        and senha % 2 != 0
        and senha % 17 == 0):

        print('Senha Forte')

    else:
        print('Senha Fraca')

except(ValueError):
    print('Digite apenas números')

